  "description": "This OpenCode V2 plugin adds the current model catalog to the Eden AI EU provider. The catalog contains models, capabilities, context limits, and prices.",
  "license": "MIT",
  "author": "Philipp Ahlner",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/ahlner/opencode-edenai-catalog.git"
  },
  "keywords": [
    "opencode",
    "plugin",
    "edenai",
    "provider",
    "model-catalog"
  ],
  "type": "module",
  "exports": {
    ".": "./src/index.ts"
  },
  "dependencies": {
    "@opencode/plugin": "^2.0.22",
    "@opencode/schema": "^2.0.22"
  }
}
